// Build a short alert message from the error details n8n sends.
const e = $input.first().json;
const execution = e.execution || {};
const error = execution.error || (e.trigger && e.trigger.error) || {};

// Telegram uses Markdown: remove characters that break it (_ * ` [ ])
function clean(value) {
  return String(value || '-').replace(/[_*`\[\]]/g, ' ');
}

// Indian time, easy to read
const time = new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' });

const text =
  '🚨 ShaikMart workflow failed\n' +
  'Workflow: ' + clean(e.workflow && e.workflow.name) + '\n' +
  'Failed node: ' + clean(execution.lastNodeExecuted || (error.node && error.node.name)) + '\n' +
  'Error: ' + clean(String(error.message || 'Unknown error').slice(0, 300)) + '\n' +
  'Execution ID: ' + clean(execution.id) + '\n' +
  'Time: ' + clean(time);

return [{ json: { text: text } }];
